/* ❌ OLD: Media queries key off the VIEWPORT. The card's layout flips
   at 700px of screen width — but the card may live in a 300px sidebar
   or a 900px hero, so the same component renders wrongly in one of them. */

.card {
  display: flex;
  flex-direction: column;
}

@media (min-width: 700px) {
  .card {
    flex-direction: row; /* ❌ OLD: viewport-tied breakpoint */
  }
}

/* In a sidebar the card stays cramped in column mode at 1200px viewport;
   in a wide hero it flips to row even when it has little room. The
   component cannot adapt to its actual placement. */

/* ✅ NEW: The card wrapper is a container, and the query reacts to the
   card's OWN width. The same component now adapts per placement. */

.card-wrap {
  container-type: inline-size; /* ✅ NEW: establishes the containment context */
}

.card {
  display: flex;
  flex-direction: column;
}

@container (min-width: 400px) {
  .card {
    flex-direction: row; /* ✅ NEW: flips when the CONTAINER is wide enough */
  }
}

/* In a 300px sidebar the card stays column; in a 900px hero it flips to
   row — both correct, driven by the container, not the viewport. */
